-- 2026-11-11 知识点精修：node 42 总线原文恢复 + 地址总线 OCR 残片修复
-- 总线、地址总线均按 PDF 原文；仅合并 2^16/2^20 示例与 n 位公式，删除单独的“20=1MB”残片。
begin;
create temp table _kb_addr_fix(node_id integer primary key, blocks jsonb not null) on commit drop;
insert into _kb_addr_fix values (42, $kb$[{"t":"list","id":"a1-1-1-3-b1","imp":"core","items":["1、==总线用于连接 CPU、内存、外存和各种 I/O 设备并在它们之间传输信息的一组共享的传输线及其控制电路。==","（1）==CPU 总线（前端总线）==：用于连接CPU 和主存之间的总线。一般CPU 总线的数据线条目为CPU 位数。目前CPU(i3/i5/i7/i9）都是64 位。","（2）==I/O 总线==：用于连接主存和I/O 设备（包括外设）总线（目前使用的PCI 和PCI-E）","（3）按总线功能或信号类型分为：==地址总线（传输地址信号）、数据总线（传输数据信号）、控制总线（传输控制信号）。==","①、^^数据总线用于传送数据信息。^^数据总线是双向三态形式的总线，它既可以把CPU 的数据传送到存储器或I/O 接口等其他部件，也可以将其他部件的数据传送到CPU。数据总线的位数是微型计算机的一个重要指标，通常与微处理器的字长相一致。","②、^^地址总线是专门用来传送地址的，^^由于地址只能从 CPU 传向外部存储器或：I/O 端口，所以地址总线总是单向三态的，这与数据总线不同。==地址总线的位数决定了 CPU 可直接寻址的内存空间大小。==例如，8 位微机的地址总线为 16 位，则其最大可寻址空间为 2^16=64KB；16 位微机的地址总线为 20 位，则其可寻址空间为 2^20=1MB。一般来说，@@若地址总线为 n 位，则可寻址空间为 2^n 字节。@@","③、^^控制总线用来传送控制信号和时序信号。^^控制信号中，有的是微处理器送往存储器和I/O 接口电路的，如读/写信号、片选信号、中断响应信号等；也有的是其他部件反馈给CPU 的，如中断申请信号、复位信号、总线请求信号、设备就绪信号等。因此，控制总线的传送方向由具体控制信号而定，一般是双向的。","控制总线的位数要根据系统的实际控制需要而定。","（4）总线带宽：","①、总线带宽指单位时间内总线上可以传输的最大的数据量。","②、@@总线带宽（MB/s）=（总线位宽/8）×总线工作频率（MHz）×每个总线周期数据传输的次数。@@","2、==I/O 控制器与常见输入输出设备接口==：I/O 控制器（input 和 output）负责输入输出控制。 常见输入设备：鼠标、键盘、扫描仪、数码相机、摄像头。 常见输出设备：显示器、打印机、绘图仪。 常用接口：串行口 COM（9 针）；并行口 LPT1（接打印机）；VGA 口（接显示器）；PS/2 口（接鼠标、键盘）；USB 高速通用串行接口，可接鼠标、键盘、外置光驱、U 盘、打印机等，有 1.1 和 2.0 两种类型，1.1 全速速率为 12Mb/s（约 1.5MB/s）。","3、==PC 机组成==：","1. ^^输入单元（input unit）^^：==计算机的“接收”部分==，从各种输入设备接收信息（数据和计算机程序），并将这些信息放到其他单元中，使信息得以处理。如今大多数信息通过键盘和鼠标输入计算机，将来也可能通过语音输入或扫描图形获得。","2. ^^输出单元（output unit）^^：==计算机的“发送”部分==，将计算机处理过的信息送到不同输出设备中，向计算机外部提供所需的信息。如今大多数信息通过屏幕显示、书面打印或用于控制其他设备输出。","3. ^^内存单元（memory unit）^^：==计算机中快速访问、低容量的“库存”部分==。","4、==衡量计算机性能的中央处理器==：==衡量一台计算机的好坏主要看中央处理器 CPU==，一台计算机可以有多个中央处理器。 CPU 的组成：运算器（算术运算与逻辑运算）、控制器（译码、取指、记录指令）、寄存器（速度最快，Cache 次之）。 决定硬件性能的因素：晶体管数量（关键）、处理器架构、硬件指令集、工作频率（主频）。","5、==寄存器组、多核与并行处理==：寄存器组（GPR）临时存放在 ALU 中运算的数据和运算结果。 多核指的是==一个 CPU 芯片里面有多个 CPU（内核）==。 采用多个 CPU 实现超高计算的技术称为“并行处理”，采用这种技术的计算机系统称为“多处理器系统”。“多处理器系统”特指有多个 CPU 的计算机系统。","6、^^鼠标滚轮的作用^^：^^某些鼠标器左右两按键的中间有一个滚轮^^，它的作用通常是控制屏幕内容上下移动，与窗口右边框滚动条的功能一样。注意：按动鼠标按键后，计算机具体做什么，由正在运行的软件决定。","7、^^处理器、微处理器与并行处理^^：==处理器==：^^能高速地进行算术运算和逻辑运算^^，负责对输入信息进行各种处理的部件。 微处理器：简称 μP 或 MP，通常指使用单片大规模集成电路制成的、具有运算和控制功能的处理器。 并行处理和多处理器系统：使用多个 CPU（中央处理器，2、4、8 个或更多）实现超高速计算的技术称为“并行处理”，采用这种技术的计算机系统称为“多处理器系统”。","8、^^程序（指令）和数据均以二进制编码表示，均存放在存储器中。^^","9、程序运行时候，CPU 内存中一条一条取出指令和相应的数据，按指令操作码的规定，对数据进行运算处理，直到程序执行完毕为止。","10、==指令是构成程序的基本单位，程序是由一连串指令组成。==","11、==指令==的组成：==操作码==和==操作数（地址码）==。==操作码不可少，地址码可以没有。==","（1）操作码：指出CPU 应执行何种操作的一个命令词，例如加、减、乘、除等","（2）操作数（地址码）：指出该指令所操作(处理)的数据或者数据所在位置","12、指令的执行过程：==取指令->指令译码->执行指令->保存==","（1）==取指令==：CPU 的控制器从存储器读取一条指令并放入指令寄存器","（2）==指令译码==：^^指令寄存器中的指令经过译码，决定该指令应进行何种操作、操作数在哪里^^","（3）==执行指令==：取出操作数并进行相应运算","（4）==保存==：运算结果的保存至寄存器，有时候也会保存至内存中。","13、==指令系统==：==CPU 可执行的全部指令称为该CPU 的指令系统，即它的机器语言==","14、^^一般同一公司为解决软件兼容性问题，采用“向下兼容方式”开发新的处理器，即所有新处理器均保留老处理器的全部指令，同时还扩充功能更强的新指令。^^","15、^^智能手机和平板电脑使用的是ARM 架构的CPU,和PC 上的CPU 的指令系统不一样，所在不兼容。^^","16、==内存储器与外存储器的区别==：存储器分为==内存储器和外存储器==。外存不直接影响计算机的运行速度，影响计算机速度的主要是 CPU 和内存。 内存：运行速度快，断电后信息消失，存储容量小，由半导体芯片构成，可直接与 CPU 交换数据。 外存：运行速度慢，断电后信息不丢失，存储容量大，由磁性介质、光学介质或闪存芯片构成，不能直接与 CPU 交换数据，需先调入内存。 存储器的存取时间是指从 CPU 给出存储器地址开始，到存储器读出数据并送到 CPU（或把 CPU 的数据写入存储器）所需要的时间。","17、==存储器的层状塔式结构==：==内存储器和外存储器组成一个层状的塔式结构==。 1）目的：优化存储器的性能价格比。 2）存储器按读写速度由高到低排列：Cache、RAM、硬盘、光盘。","18、==内存储器、外存储器与系统总线概述==：^^1）内存储器^^：==计算机的内存储器是指 ROM 和 RAM==，它是外存与 CPU 进行沟通的桥梁，计算机中所有程序的运行都在内存中进行。内存性能的强弱影响计算机整体发挥的水平。内存也称内存储器和主存储器，用于暂时存放 CPU 中的运算数据以及与硬盘等外部存储器交换的数据。 2）外存储器：指除计算机内存及 CPU 缓存以外的储存器，此类储存器一般断电后仍然能保存数据。 3）系统总线：总线是连接各个部件的信息传输线，是各个部件共享的传输介质。总线结构的计算机举例：单总线结构框图、面向 CPU 的双总线结构框图、以存储器为中心的双总线结构框图。","19、==江苏省专转本计算机大类新旧考试大纲对比==：","1. ==新大纲课程 A1 计算机硬件==；旧大纲课程 A（二）计算机硬件。","2. ==新大纲课程 A1.1 计算机基本原理==；旧大纲课程 A1 计算机基本原理。","3. 新大纲 A1.1.1 计算机发展及分类、软件概述、硬件概述（了解）；旧大纲 A（1）计算机发展及分类、软件概述、硬件概述（了解）。","4. 新大纲 A1.1.2 常见的输入设备和输出设备、中央处理器（了解）；旧大纲 A（2）常见的输入设备、常见的输出设备、中央处理器概述、奔腾处理器特点（了解）。","20、==主存储器的功能与原理==：主存是 CPU 可直接访问的存储器，用于==存放供 CPU 处理的指令和数据==。 特点：","- ==以字节为单位进行连续编址==，每个存储单元为 1 个字节（8 个二进位）。","- ^^存储容量^^：==主存储器中所包含的存储单元的总数（单位 MB 或 GB）==。","- ^^存取时间^^：==从 CPU 送出内存单元的地址码开始==，到主存读出数据并送到 CPU（或把 CPU 数据写入主存）所需要的时间，单位 ns，1 ns 10⁻⁹ s。","21、==地址总线宽度决定可访问内存容量==：CPU 地址总线的位数（根数、宽度）决定了 ==CPU 可访问的内存容量大小==。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-1-3-b2","imp":"core","kind":"tip","text":"存储系统按速度由高到低排列为：==寄存器 > 高速缓存 Cache > 内存储器（RAM/ROM） > 外存储器（SSD/机械硬盘/光盘）==；系统总线按传送信号划分为==数据总线（双向传送数据）、地址总线（单向传送物理地址，决定最大寻址空间）、控制总线（双向传送控制/时序信号）==。","title":"考向复习提示：存储层级塔式结构与系统总线分类"},{"t":"callout","id":"a1-1-1-3-b3","imp":"core","kind":"trap","text":"若 CPU 的地址总线为 32 位，则其最大可直接寻址空间为 ==2^32 字节 = 4 GB==；若地址总线为 36 位，最大寻址空间为 ==2^36 字节 = 64 GB==；常考陷阱是将寻址空间误算为“字”而非“字节”，计算机内存始终以==字节（8 位）==为基本编址单位！","title":"高频易错陷阱：地址总线宽度与寻址能力计算"}]$kb$::jsonb);
do $$
declare old_rev record; v_rev integer; n integer;
begin
  select rev_no, html, search_text, source_ref into old_rev
    from kb_revision where node_id=42 and rev_no=(select published_rev from kb_entry where node_id=42);
  if not found then raise exception 'node 42 找不到已发布 revision'; end if;
  select coalesce(max(rev_no),0)+1 into v_rev from kb_revision where node_id=42;
  insert into kb_revision(node_id,rev_no,blocks,html,search_text,source_ref)
  values (42,v_rev,(select blocks from _kb_addr_fix),old_rev.html,old_rev.search_text,old_rev.source_ref);
  update kb_entry set published_rev=v_rev, updated_at=now() where node_id=42;
  select count(*) into n
    from _kb_addr_fix f,
         jsonb_array_elements(f.blocks) b,
         jsonb_array_elements_text(coalesce(b->'items', '[]'::jsonb)) s
   where f.node_id = 42 and s like '20=1MB%';
  if n <> 0 then raise exception '仍存在 20=1MB 残片'; end if;
end $$;
commit;
